package net.civeira.phylax.features.access.tenantconfig.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class DcrAllowedAuthMethodsVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property dcr allowed auth methods of tenant config ")
  void test_dcr_allowed_auth_methods_v_o_builder() {
    Assertions.assertFalse(
        DcrAllowedAuthMethodsVO.nullValue().getDcrAllowedAuthMethods().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(
        DcrAllowedAuthMethodsVO.tryFrom(null).getDcrAllowedAuthMethods().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals("one",
        DcrAllowedAuthMethodsVO.from("one").getDcrAllowedAuthMethods().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class,
        () -> DcrAllowedAuthMethodsVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", DcrAllowedAuthMethodsVO.from("one").toString());
  }
}
